/**
 * Minimal replacement for maven-resources-plugin:resources — copies the project's
 * declared main resources into build.outputDirectory without filtering.
 */
public class ResourcesMojo extends AbstractMojo {

    private MavenProject project;

    @Override
    public void execute() throws MojoExecutionException {
        copyResources(project.getBuild().getResources(), project.getBuild().getOutputDirectory());
    }

    protected void copyResources(List<Resource> resources, String outputDirectory) throws MojoExecutionException {
        Path output = Path.of(outputDirectory);
        try {
            Files.createDirectories(output);
            for (Resource resource : resources) {
                Path sourceDir = Path.of(resource.getDirectory());
                if (!Files.isDirectory(sourceDir)) {
                    continue;
                }
                Path destination = output;
                String targetPath = resource.getTargetPath();
                if (targetPath != null && !targetPath.trim().isEmpty()) {
                    destination = output.resolve(targetPath);
                    Files.createDirectories(destination);
                }
                try (Stream<Path> walk = Files.walk(sourceDir)) {
                    for (Path file : (Iterable<Path>) walk.filter(Files::isRegularFile)::iterator) {
                        Path target = destination.resolve(sourceDir.relativize(file));
                        if (target.getParent() != null) {
                            Files.createDirectories(target.getParent());
                        }
                        Files.copy(file, target, StandardCopyOption.REPLACE_EXISTING);
                    }
                }
            }
        } catch (IOException e) {
            throw new MojoExecutionException("Failed to copy resources to " + output, e);
        }
    }

