import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.project.MavenProject;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Comparator;
import java.util.jar.JarEntry;
import java.util.jar.JarOutputStream;
import java.util.jar.Manifest;
import java.util.stream.Stream;

/**
 * Minimal replacement for maven-jar-plugin:jar — packages build.outputDirectory into
 * build.directory/finalName.jar with a bare manifest. The Spring Boot repackage goal
 * then turns this thin jar into the executable fat jar.
 */
public class JarMojo extends AbstractMojo {

    private MavenProject project;

    @Override
    public void execute() throws MojoExecutionException {
        Path outputJar = Path.of(project.getBuild().getDirectory(),
                project.getBuild().getFinalName() + ".jar");
        Path classesDir = Path.of(project.getBuild().getOutputDirectory());
        try {
            Files.createDirectories(outputJar.getParent());
            Manifest manifest = new Manifest();
            manifest.getMainAttributes().putValue("Manifest-Version", "1.0");
            try (JarOutputStream out = new JarOutputStream(
                    Files.newOutputStream(outputJar, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING),
                    manifest)) {
                if (Files.isDirectory(classesDir)) {
                    try (Stream<Path> walk = Files.walk(classesDir)) {
                        for (Path file : walk.filter(Files::isRegularFile)
                                .sorted(Comparator.comparing(Path::toString))::iterator) {
                            JarEntry entry = new JarEntry(
                                    classesDir.relativize(file).toString().replace('\\', '/'));
                            entry.setTime(Files.getLastModifiedTime(file).toMillis());
                            out.putNextEntry(entry);
                            Files.copy(file, out);
                            out.closeEntry();
                        }
                    }
                }
            }
            getLog().info("Built jar " + outputJar);
        } catch (IOException e) {
            throw new MojoExecutionException("Failed to build jar " + outputJar, e);
        }
    }

    public void setProject(MavenProject project) {
        this.project = project;
    }
}
